#![forbid(unsafe_code)]
//! Two-crate downstream acceptance (V3-L14, V3-L15 runtime part, V3-L11
//! cross-crate part): every type exercised here was generated by `api!` in
//! `concord-downstream-api` and is consumed only through its public surface.

use std::future::IntoFuture;
use std::num::NonZeroU32;
use std::time::Duration;

use concord::endpoint::ResponseRequest;
use concord::http::SafeProxy;
use concord::pagination::{CollectAll, CollectPrefix, Pages, Prefix};
use concord::{
    ApiError, ApiResponse, CallOptions, CancellationToken, ControlError, ControlSummary,
    RequestControls,
};
use concord_downstream_api::inventory_api::InventoryApiBuilder;
use concord_downstream_api::inventory_api::shop::{
    GadgetRequest, Shop, WidgetRequest, WidgetsRequest,
};
use concord_downstream_api::metered_api::accounts::{Accounts, UsageRequest};
use concord_downstream_api::{AccountId, Gadget, InventoryApi, MeteredApi, ShardKey, Widget};
use concord_downstream_app::{CannedRequest, execute, widget_and_gadget};
use concord_test_support::proxy::ConnectProxy;
use concord_test_support::tls::TlsServer;

fn assert_request<R, O>()
where
    R: RequestControls + IntoFuture<Output = Result<O, ApiError>>,
{
}

fn assert_clone<T: Clone>() {}

#[test]
fn downstream_named_requests_implement_controls_future_and_their_own_setters() {
    // V3-L14: the downstream-generated named requests themselves implement
    // the open controls trait and IntoFuture, as do the library terminals.
    assert_request::<WidgetRequest, Widget>();
    assert_request::<GadgetRequest, Gadget>();
    assert_request::<WidgetsRequest, Vec<Widget>>();
    assert_request::<ResponseRequest<Widget>, ApiResponse<Widget>>();
    assert_request::<CollectPrefix<Widget>, Prefix<Widget>>();
    assert_request::<CollectAll<Widget>, Vec<Widget>>();

    // Their own generated setters and terminals are inherent methods.
    let _: fn(WidgetRequest, String) -> WidgetRequest = WidgetRequest::set_view;
    let _: fn(WidgetRequest, Option<String>) -> WidgetRequest = WidgetRequest::replace_view;
    let _: fn(WidgetRequest, Option<String>) -> WidgetRequest = WidgetRequest::set_view_if_some;
    let _: fn(WidgetRequest) -> WidgetRequest = WidgetRequest::omit_view;
    let _: fn(WidgetsRequest, NonZeroU32) -> WidgetsRequest = WidgetsRequest::set_limit;
    let _: fn(WidgetsRequest) -> WidgetsRequest = WidgetsRequest::reset_limit;
    let _: fn(WidgetsRequest, u64) -> WidgetsRequest = WidgetsRequest::set_offset;
    let _: fn(WidgetsRequest, u32) -> Pages<Widget> = WidgetsRequest::pages;
    let _: fn(WidgetsRequest, NonZeroU32) -> CollectAll<Widget> = WidgetsRequest::collect_all;
    let _: fn(WidgetRequest) -> ResponseRequest<Widget> = WidgetRequest::response;
    let _: fn(&InventoryApi, String) -> Shop = InventoryApi::shop;
    let _: fn(&Shop, String) -> WidgetRequest = Shop::widget;
    let _: fn(InventoryApiBuilder, String) -> InventoryApiBuilder = InventoryApiBuilder::set_tenant;
    let _: fn(InventoryApiBuilder, String) -> InventoryApiBuilder = InventoryApiBuilder::set_trace;
    let _: fn(InventoryApiBuilder) -> InventoryApiBuilder = InventoryApiBuilder::omit_trace;

    // The common controls are also inherent on the generated types.
    let _: fn(WidgetRequest, Duration) -> Result<WidgetRequest, ControlError> =
        WidgetRequest::timeout;
    let _: fn(WidgetRequest) -> WidgetRequest = WidgetRequest::reset_timeout;
    let _: fn(WidgetRequest, CancellationToken) -> Result<WidgetRequest, ControlError> =
        WidgetRequest::cancel_with;
    let _: fn(WidgetRequest, &CallOptions) -> WidgetRequest = WidgetRequest::with_options;
    let _: fn(&WidgetRequest) -> ControlSummary = WidgetRequest::control_summary;

    // V3-L11 (cross-crate): body-free requests, scopes and clients are Clone
    // although their outputs (`Widget`, `Gadget`) are not.
    assert_clone::<InventoryApi>();
    assert_clone::<Shop>();
    assert_clone::<WidgetRequest>();
    assert_clone::<GadgetRequest>();
    assert_clone::<WidgetsRequest>();
}

#[test]
fn the_second_downstream_clients_named_request_implements_the_same_bounds() {
    // V3-L14: the api crate's second client (`MeteredApi`) introduces its
    // own named request, which itself implements the open controls trait
    // and IntoFuture, like every other introduced downstream request.
    assert_request::<UsageRequest, Widget>();

    // Its constructor, terminal and the common controls are inherent methods.
    let _: fn(&MeteredApi, AccountId) -> Accounts = MeteredApi::accounts;
    let _: fn(&Accounts, ShardKey, u32) -> UsageRequest = Accounts::usage;
    let _: fn(UsageRequest) -> ResponseRequest<Widget> = UsageRequest::response;
    let _: fn(UsageRequest, Duration) -> Result<UsageRequest, ControlError> = UsageRequest::timeout;
    let _: fn(UsageRequest) -> UsageRequest = UsageRequest::reset_timeout;
    let _: fn(UsageRequest, CancellationToken) -> Result<UsageRequest, ControlError> =
        UsageRequest::cancel_with;
    let _: fn(UsageRequest, &CallOptions) -> UsageRequest = UsageRequest::with_options;
    let _: fn(&UsageRequest) -> ControlSummary = UsageRequest::control_summary;

    // V3-L11 (cross-crate): body-free, so Clone although `Widget` is not.
    assert_clone::<MeteredApi>();
    assert_clone::<Accounts>();
    assert_clone::<UsageRequest>();
}

fn planning_client() -> InventoryApi {
    InventoryApi::builder()
        .set_tenant("acme".to_owned())
        .build()
        .expect("planning client")
}

#[test]
fn downstream_setters_change_the_planned_request() {
    let client = planning_client();
    let shop = client.shop("s1".to_owned());
    let url = |request: WidgetRequest| request.plan().expect("plan").observed_url().to_owned();
    let base = "https://localhost/v1/shops/s1/widgets/w1?tenant=acme";
    assert_eq!(url(shop.widget("w1".to_owned())), base);
    assert_eq!(
        url(shop.widget("w1".to_owned()).set_view("full".to_owned())),
        format!("{base}&view=full")
    );
    assert_eq!(
        url(shop
            .widget("w1".to_owned())
            .set_view("full".to_owned())
            .omit_view()),
        base
    );
    assert_eq!(
        url(shop
            .widget("w1".to_owned())
            .set_view("full".to_owned())
            .set_view_if_some(None)),
        format!("{base}&view=full"),
        "None is no new opinion"
    );
    assert_eq!(
        url(shop
            .widget("w1".to_owned())
            .set_view("full".to_owned())
            .replace_view(None)),
        base,
        "an exact None is absence"
    );

    let list = |request: WidgetsRequest| request.plan().expect("plan").observed_url().to_owned();
    let list_base = "https://localhost/v1/shops/s1/widgets?tenant=acme";
    assert_eq!(
        list(shop.widgets()),
        format!("{list_base}&offset=0&limit=1")
    );
    let five = NonZeroU32::new(5).expect("nonzero");
    assert_eq!(
        list(shop.widgets().set_limit(five)),
        format!("{list_base}&offset=0&limit=5")
    );
    assert_eq!(
        list(shop.widgets().set_limit(five).reset_limit()),
        format!("{list_base}&offset=0&limit=1")
    );

    // A generated request's controls narrow only and report through the
    // value-free summary.
    let summary = shop
        .gadget("g".to_owned())
        .with_options(&CallOptions::new().cap_sends(4))
        .with_options(&CallOptions::new().cap_sends(9))
        .control_summary();
    assert_eq!(summary.send_cap(), Some(4));
}

struct Loopback {
    server: TlsServer,
    _tunnel: ConnectProxy,
    client: InventoryApi,
}

fn loopback() -> Loopback {
    let server = TlsServer::start().expect("TLS loopback");
    let tunnel = ConnectProxy::start(server.address()).expect("CONNECT tunnel");
    let proxy = SafeProxy::parse(tunnel.url()).expect("safe proxy");
    let root = server.certificate_pem();
    let client = InventoryApi::builder()
        .set_tenant("acme".to_owned())
        .set_trace("trace-7".to_owned())
        .configure_http(move |http| {
            http.http1_only()
                .proxy(proxy)
                .add_root_certificate_pem(root)
        })
        .build()
        .expect("downstream client");
    Loopback {
        server,
        _tunnel: tunnel,
        client,
    }
}

fn queue_json(server: &TlsServer, body: &str) {
    server
        .queue_response_with_headers(
            200,
            &[("content-type", "application/json")],
            body.as_bytes().to_vec(),
        )
        .expect("queue JSON");
}

#[tokio::test(flavor = "current_thread")]
async fn distinct_requests_and_terminals_pass_the_consumers_generic_helper() {
    let Loopback {
        server,
        _tunnel,
        client,
    } = loopback();
    let options = CallOptions::new().cap_sends(2);

    // Two distinct endpoint request types through one helper.
    queue_json(&server, r#"{"id":"w1","name":"Widget"}"#);
    queue_json(&server, r#"{"id":"g1"}"#);
    let (widget, gadget) = widget_and_gadget(&client, "s1", "w1", "g1", &options)
        .await
        .expect("widget and gadget");
    assert_eq!(
        widget,
        Widget {
            id: "w1".to_owned(),
            name: "Widget".to_owned()
        }
    );
    assert_eq!(
        gadget,
        Gadget {
            id: "g1".to_owned()
        }
    );

    // A ResponseRequest terminal and a collection terminal.
    let shop = client.shop("s1".to_owned());
    queue_json(&server, r#"{"id":"w2","name":"Second"}"#);
    let response = execute(shop.widget("w2".to_owned()).response(), &options)
        .await
        .expect("response");
    assert_eq!(response.status().as_u16(), 200);
    assert_eq!(response.value().name, "Second");
    queue_json(&server, r#"[{"id":"a","name":"A"},{"id":"b","name":"B"}]"#);
    queue_json(&server, r#"[{"id":"c","name":"C"}]"#);
    let all = execute(
        shop.widgets()
            .set_limit(NonZeroU32::new(2).expect("nonzero"))
            .collect_all(NonZeroU32::new(5).expect("nonzero")),
        &options,
    )
    .await
    .expect("collect all");
    let ids: Vec<&str> = all.iter().map(|widget| widget.id.as_str()).collect();
    assert_eq!(ids, ["a", "b", "c"]);

    let requests = server.requests();
    assert_eq!(requests.len(), 5);
    assert_eq!(
        requests[0].target(),
        "/v1/shops/s1/widgets/w1?tenant=acme&view=full"
    );
    assert_eq!(requests[1].target(), "/v1/shops/s1/gadgets/g1?tenant=acme");
    assert_eq!(requests[2].target(), "/v1/shops/s1/widgets/w2?tenant=acme");
    assert_eq!(
        requests[3].target(),
        "/v1/shops/s1/widgets?tenant=acme&offset=0&limit=2"
    );
    assert_eq!(
        requests[4].target(),
        "/v1/shops/s1/widgets?tenant=acme&offset=2&limit=2"
    );
    for request in &requests {
        assert_eq!(request.method(), "GET");
        assert_eq!(request.header("x-trace"), Some("trace-7"));
        assert_eq!(request.header("host"), Some("localhost"));
    }
}

#[tokio::test(flavor = "current_thread")]
async fn the_second_downstream_clients_request_passes_the_consumers_generic_helper() {
    // V3-L14: `MeteredApi`'s `UsageRequest` (introduced by the api crate's
    // other client) runs through the same consumer helper over TLS.
    let server = TlsServer::start().expect("TLS loopback");
    let tunnel = ConnectProxy::start(server.address()).expect("CONNECT tunnel");
    let proxy = SafeProxy::parse(tunnel.url()).expect("safe proxy");
    let root = server.certificate_pem();
    let client = MeteredApi::builder()
        .set_region("EU-West".to_owned())
        .configure_http(move |http| {
            http.http1_only()
                .proxy(proxy)
                .add_root_certificate_pem(root)
        })
        .configure_runtime(|runtime| {
            runtime.rate_limiter(std::sync::Arc::new(
                concord::rate_limit::NoopRateLimiter::new(),
            ))
        })
        .build()
        .expect("metered client");
    let usage = client.accounts(AccountId::new(7)).usage(ShardKey(3), 20);
    let capped = usage.clone().with_options(&CallOptions::new().cap_sends(1));
    assert_eq!(capped.control_summary().send_cap(), Some(1));

    queue_json(&server, r#"{"id":"u20","name":"Usage"}"#);
    let widget = execute(usage, &CallOptions::new().cap_sends(1))
        .await
        .expect("usage through the generic helper");
    assert_eq!(
        widget,
        Widget {
            id: "u20".to_owned(),
            name: "Usage".to_owned()
        }
    );
    let requests = server.requests();
    assert_eq!(requests.len(), 1);
    assert_eq!(requests[0].method(), "GET");
    assert_eq!(requests[0].target(), "/metered/usage/20");
    assert_eq!(requests[0].header("host"), Some("localhost"));
}

#[tokio::test(flavor = "current_thread")]
async fn a_foreign_request_controls_implementation_gains_no_native_access() {
    let Loopback {
        server,
        _tunnel,
        client,
    } = loopback();
    let captured = client
        .shop("s1".to_owned())
        .gadget("g1".to_owned())
        .control_summary();

    // The open trait lets the helper accept the foreign type ...
    let canned = CannedRequest::new(
        Gadget {
            id: "canned".to_owned(),
        },
        captured.clone(),
    );
    let narrowed = canned.with_options(&CallOptions::new().cap_sends(1));
    assert_eq!(narrowed.options_applied(), 1);
    // ... but it cannot make core enforce or report anything: the summary is
    // whatever it was handed, and awaiting it never reaches the provider.
    assert_eq!(narrowed.control_summary(), captured);
    let value = execute(narrowed, &CallOptions::new().cap_sends(0))
        .await
        .expect("canned value");
    assert_eq!(
        value,
        Gadget {
            id: "canned".to_owned()
        }
    );
    assert!(
        server.requests().is_empty(),
        "no native request was created"
    );

    // The same helper with a genuine generated request honours the caps
    // through the managed executor: zero sends means no dispatch.
    let error = execute(
        client.shop("s1".to_owned()).gadget("g1".to_owned()),
        &CallOptions::new().cap_sends(0),
    )
    .await
    .expect_err("zero sends");
    assert_eq!(
        error.dispatch_knowledge(),
        concord::DispatchKnowledge::NotDispatched
    );
    assert!(server.requests().is_empty());

    queue_json(&server, r#"{"id":"g1"}"#);
    let gadget = execute(
        client.shop("s1".to_owned()).gadget("g1".to_owned()),
        &CallOptions::new(),
    )
    .await
    .expect("gadget");
    assert_eq!(
        gadget,
        Gadget {
            id: "g1".to_owned()
        }
    );
    assert_eq!(server.requests().len(), 1);
}
